-- ============================================================
-- Kenworthy 100-Year Film Archive -> public.historical_screenings
-- Source: "Full List of Movies at Palouse Theaters 1926 to 2026.xlsx"
-- Generated by src/lib/parseHistoricalXlsx.ts (the same parser ArchiveTab uses).
-- Rows: 21452 | Years: 1926-2025
-- Venues: Kenworthy=10028, Nuart=4150, Cordova=2537, Big Sky=2375, Audian=1613, Vandal=749
-- ============================================================

BEGIN;

-- Refuse to run twice: this script assumes an empty archive.
DO $$
BEGIN
  IF (SELECT count(*) FROM public.historical_screenings) > 0 THEN
    RAISE EXCEPTION 'historical_screenings is not empty (% rows) - clear it first or skip this import',
      (SELECT count(*) FROM public.historical_screenings);
  END IF;
END $$;












































COMMIT;

